import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const read = (name) => readFileSync(join(root, name), 'utf8').replaceAll('\r\n', '\n');
const stripShebang = (s) => s.replace(/^#![^\n]*\n/, '');
const delimiter = 'NEXTCLOUD_GUEST_SCRIPT_EOF';
const guest = read('src/guest.sh');
if (guest.split('\n').includes(delimiter)) throw new Error('Guest heredoc delimiter collision');
const output = '#!/usr/bin/env bash\n' +
  '# Generated by node scripts/build.mjs from src/*.sh. Review source or this entire file.\n' +
  '# Self-contained: no additional project scripts are downloaded or sourced at runtime.\n\n' +
  stripShebang(read('src/validation.sh')) + '\n' +
  `render_guest() {\n    cat <<'${delimiter}'\n${guest}${delimiter}\n}\n\n` +
  stripShebang(read('src/host.sh')) + '\n' + stripShebang(read('src/main.sh'));
const target = join(root, 'install.sh');
if (process.argv.includes('--check')) {
  if (read('install.sh') !== output) throw new Error('install.sh is stale; run node scripts/build.mjs');
  console.log('Self-contained installer matches source.');
} else {
  writeFileSync(target, output, { mode: 0o755 });
  console.log('Built install.sh.');
}
